#!/usr/bin/env python3
"""Genera informe desde evidencia filtrada; no accede al host."""
import json,re,pathlib
x=json.load(open('docs/roadmap/evidence/2026-11-13-host-inventory.json'));G=2**30
m={k:int(v.split()[0])*1024 for k,v in (l.split(':',1) for l in x['meminfo'].splitlines())}
g=x['guests'];total=sum(a['maxmem'] or 0 for a in g);non=sum(a['maxmem'] or 0 for a in g if a['config'].get('onboot','0')!='1');active=sum(a['maxmem'] or 0 for a in g if a['status']=='running');reserve=4*G
lv=x['lvm_json']['report'][0]['lv'];pool=next(a for a in lv if a['lv_name']=='data');virtual=sum(float(a['lv_size']) for a in lv if a['pool_lv']=='data');physical=float(pool['lv_size'])
f=lambda b:f'{b/G:.2f} GiB'
s=['# Inventario del host Proxmox VE para IA local','',f"Fecha: 13 de noviembre de 2026 (Europe/Madrid). Inicio de captura UTC: {x['utc']}.", 'Lecturas como root en el host `pve`, por SSH estricto. Sin instalaciones, benchmarks, inferencias ni cambios operativos. Medidas sucesivas, no instantánea atómica.','', '## 1. Resumen ejecutivo','', '| Concepto | Resultado |','|---|---|', '| CPU | Intel Core i5-6500, 4 núcleos/4 hilos; AVX/AVX2/FMA/F16C sí; AVX-512 no |',f"| RAM | 32 GiB instalados; utilizable {f(m['MemTotal'])}; máximo SMBIOS 32 GB |",f"| Libre física sin caché (MemFree) | {f(m['MemFree'])} |",f"| Disponible estimada por Linux (MemAvailable) | {f(m['MemAvailable'])}; incluye memoria recuperable |",f'| Comprometida guests (Σ maxmem, incluidos apagados) | {f(total)} |', '| ARC actual / máximo | 960 bytes / 15.62 GiB; mínimo 1 GiB; sin pools ZFS activos |', '| RAM tipo/velocidad/canales | 2×16 GB DDR4 SODIMM; 2133 MT/s declarados y configurados; DIMM1 ChannelB y DIMM3 ChannelA |',f"| Swap | {f(m['SwapTotal'])} total; {f(m['SwapTotal']-m['SwapFree'])} usada |", '| GPU | Intel HD Graphics 530 integrada; ninguna dedicada detectada |','', '## 2. Presupuesto de RAM para IA','', f"Reserva de planificación propuesta para host: 4 GiB, no medición de consumo fijo ni autorización de cambios. Presupuesto estricto = max(0, RAM utilizable − compromisos − reserva).",f"- (a) Todos los guests: max(0, {m['MemTotal']/G:.2f} − {total/G:.2f} − 4) = **0 GiB**; déficit contable {(total+reserve-m['MemTotal'])/G:.2f} GiB.",f"- Solo guests actualmente en marcha: compromisos {f(active)}; también 0 GiB sin sobrecompromiso.",f"- (b) Si se apagan y dejan de reservar los que tienen onboot=0: se excluyen {f(non)}; max(0, {m['MemTotal']/G:.2f} − {(total-non)/G:.2f} − 4) = **{max(0,m['MemTotal']-total+non-reserve)/G:.2f} GiB**. Apagarlos conserva la configuración: este escenario exige mantenerlos fuera de la planificación concurrente.",f"- Margen oportunista actual: MemAvailable − reserva = {max(0,m['MemAvailable']-reserve)/G:.2f} GiB. No garantiza admisión sin sobrecompromiso: los CT pueden crecer hasta sus límites.", '- (c) Limitar ARC no aporta RAM apreciable: tamaño actual 960 bytes, sin pools. El techo 15.62 GiB no es consumo real. No se modifica.', '', '## 3. Ancho de banda de memoria teórico','', '**2 × 2133 MT/s × 8 bytes = 34.128 GB/s** decimales (31.78 GiB/s). SMBIOS informa un módulo igual por canal A/B, compatible con dual channel simétrico; no prueba directamente el modo efectivo del controlador. Si solo operase un canal: 17.064 GB/s. Sin benchmark; el ancho de banda sostenido es desconocido.','', '| Slot | Ocupado | Tamaño | Tipo | Velocidad declarada/configurada | Banco |','|---|---|---|---|---|---|','| DIMM1 | Sí | 16 GB | DDR4 | 2133/2133 MT/s | ChannelB |','| DIMM3 | Sí | 16 GB | DDR4 | 2133/2133 MT/s | ChannelA |','', '## 4. Almacenamiento','', '| Storage/pool | Discos / medio | Tipo | Contenido permitido | Total | Libre | SMART |','|---|---|---|---|---|---|---|']
for a in x['storages']:
 disk='sdb USB / HDD' if a['storage']=='storage' else 'sda SATA / SSD'
 s.append(f"| {a['storage']} | {disk} | {a['type']} | {a['content']} | {f(a['total'])} | {f(a['avail'])} | PASSED |")
s += ['',f"Thin pool pve/data: tamaño físico {f(physical)}, volúmenes virtuales {f(virtual)} ({100*virtual/physical:.2f} %). Datos ocupados {pool['data_percent']} %, metadata {pool['metadata_percent']} %. El porcentaje virtual >100 % expresa sobreaprovisionamiento; no equivale a ocupación física. Snapshots/bloques compartidos impiden equiparar suma virtual y uso real.",'El VG pve no tiene espacio sin asignar (VFree=0); no sumar el libre de local y local-lvm como espacio intercambiable. No hay pools ZFS.','', '## 5. Recomendación','', 'Guardar los 20–40 GB de GGUF en un volumen del SSD `local-lvm`, ligado al CT de llama-server. Proponer también ambos rootfs en ese pool: ofrece unos 178.64 GiB físicos libres y evita la latencia del HDD USB. Dimensionar cuotas y reserva antes de provisionar; los límites virtuales ya exceden el pool. Esta es una propuesta, no un despliegue.', '`local` tiene unos 41.60 GiB libres y comparte SSD con el host: 40 GB de modelos consumirían casi todo su margen. Evitarlo para ese objetivo. Reservar HDD `storage` para copias/modelos secundarios si se acepta carga inicial más lenta. No se recomienda crear los CT hasta resolver el presupuesto concurrente de RAM.','', '## 6. VMs/CTs existentes','', '| ID | Tipo/nombre | Estado | onboot | RAM asignada / maxmem | RAM usada API | Cores | Storage/discos |','|---|---|---|---|---|---|---|---|']
for a in sorted(g,key=lambda a:a['vmid']):
 c=a['config'];disks='; '.join(k+'='+v for k,v in c.items() if k=='rootfs' or re.fullmatch(r'(scsi|sata|virtio|ide|mp|unused)\d+',k));s.append(f"| {a['vmid']} | {a['type']} {a['name']} | {a['status']} | {c.get('onboot','0 (omitido)')} | {c.get('memory','?')} MiB / {f(a['maxmem'] or 0)} | {f(a['mem'] or 0)} | {c.get('cores',a['cpus'])} | {disks} |")
s+=['','RAM usada procede de la API PVE; para LXC depende de su contabilidad de memoria y caché, no equivale a RSS exclusivo. maxmem es límite configurado, no reserva física.','', '## 7. Avisos','', '- RAM comprometida muy superior a la física; MemAvailable alto no elimina este riesgo.', '- Swap en uso (~2.47 GiB); no prueba por sí sola presión presente. No se ha vaciado.', f'- Thin pool sobre el umbral virtual del 80 % ({100*virtual/physical:.2f} %), aunque su ocupación física es 55.35 %.', '- SSD: SMART PASSED, 47 771 horas, un bloque NAND reasignado y un evento. Atributo 202 etiquetado Percent_Lifetime_Remain: normalizado 77, raw 23; interpretación exacta del fabricante no verificada, no afirmar 23 % restante. Atributo 173: normalizado 77, raw 359. HDD: PASSED, 14 638 horas y cero sectores reasignados/pendientes.', '- No hay pools ZFS: módulo y ARC residual presentes; ausencia de zfs.conf no justifica advertir consumo de 15.62 GiB.', '- Enlace eno1 a 100 Mb/s: limita transferencias externas. lscpu informa vulnerabilidades sin microcódigo; revisión fuera de este alcance.', '- top observa procesos zombie; diagnóstico de su origen queda fuera de este inventario. Carga puntual no predice latencia de inferencia.', '', '## 8. Herramientas no disponibles','', ', '.join(sorted(set(x['missing']))) or 'Ninguna de las herramientas invocadas falta. nvme no se requiere: no se detecta NVMe.', 'Estado ksmtuned: '+x['ksmtuned']+'.','', '## Anexo de lecturas filtradas','']
for k in ['pve','kernel','hostname','cpu','governor','free','meminfo','swap','ksm','ksmtuned','arcstats','zfs_conf','node','qm_list','pct_list','storage_status','storage_cfg','disks','smart','pvs','vgs','lvs','zpool','zpool_status','zfs','df','directories','gpu','network','bridges','links','uptime','top','processes']:
 v=x.get(k,'no disponible');s+=['### '+k,'','```text',v if isinstance(v,str) else json.dumps(v,indent=2,ensure_ascii=False),'```','']
s+=['### Configuración seleccionada de guests','','```json',json.dumps([{k:a[k] for k in ['vmid','config']} for a in g],indent=2,ensure_ascii=False),'```','']
text='\n'.join(s);text=text.replace('reserva).\n-', 'reserva).\n\n-');pathlib.Path('docs/roadmap/INVENTARIO-HOST-2026-11-13.md').write_text(text)
print('\n'.join(s[:40]))
